import { Rating, type RatingValueDetail } from '@absoluteui/components/rating';

const host = document.createElement('div');
const out = document.createElement('p');
document.body.append(host, out);
Rating.create(host, {
  label: 'Overall performance',
  allowHalf: true,
  required: true,
  labels: ['Needs improvement', 'Developing', 'Meets expectations', 'Exceeds expectations', 'Outstanding'],
});
host.addEventListener('aui-change', (event) => {
  const { value } = (event as CustomEvent<RatingValueDetail>).detail;
  out.textContent = value === null ? 'Not rated' : `Score ${String(value)}`;
});

import { Rating } from '@absoluteui/components/rating';

const host = document.createElement('span');
document.body.append(host);
Rating.create(host, { label: 'Customer rating', value: 4.5, allowHalf: true, display: true, size: 'sm', hideLabel: true });

